function pick(arr) { return arr[randInt(arr.length)]; }
function maybe(prob) { return Math.random() < prob; }

function jsonValue(depth = 0) {
  if (depth > 2) {
    return pick(['null', 'true', 'false', '0', '1', '1.0', '\"x\"', '\"\"']);
