  branches.push(`{"not":${simpleSchema(depth + 1)}}`);
  branches.push(`{"if":${simpleSchema(depth + 1)},"then":${simpleSchema(depth + 1)},"else":${simpleSchema(depth + 1)}}`);
  branches.push('"'{\""'$ref":"#/definitions/x","definitions":{"x":{"type":"number"}},"type":"string"}'"');
